"13\" class=\"k0\" cx=\"150\" cy=\"87\" r=\"11\"/><circle data-k=\"14\" class=\"k0\" cx=\"169\" cy=\"68\" r=\"11\"/><circle data-k=\"15\" class=\"k0\" cx=\"193\" cy=\"56\" r=\"11\"/></svg></div></div><div class=\"af\" data-cap=\"The lecture&#x27;s opening test: three cut discs, and the brain draws a triangle that isn&#x27;t there\"><div style=\"overflow-x:auto\"><svg viewBox=\"0 0 440 250\" role=\"img\" aria-label=\"Three cut discs suggesting a triangle\" style=\"width:100%;max-width:440px;min-width:280px;display:block;margin:0 auto;font-family:var(--mono)\"><text class=\"tv\" x=\"14\" y=\"24\">Closure</text><path class=\"k4\" d=\"M220 50L205 76A30 30 0 1 1 235 76Z\"/><path class=\"k4\" d=\"M128 209.3L158 209.3A30 30 0 1 1 143 183.4Z\"/><path class=\"k4\" d=\"M312 209.3L297 183.4A30 30 0 1 1 282 209.3Z\"/><g style=\"opacity:0\"><circle data-k=\"0\" class=\"k0\" cx=\"220\" cy=\"52\" r=\"11\"/><circle data-k=\"1\" class=\"k0\" cx=\"247\" cy=\"56\" r=\"11\"/><circle data-k=\"2\" class=\"k0\" cx=\"271\" cy=\"68\" r=\"11\"/><circle data-k=\"3\" class=\"k0\" cx=\"290\" cy=\"87\" r=\"11\"/><circle data-k=\"4\" class=\"k0\" cx=\"302\" cy=\"165\" r=\"11\"/><circle data-k=\"5\" class=\"k0\" cx=\"290\" cy=\"189\" r=\"11\"/><circle data-k=\"6\" class=\"k0\" cx=\"271\" cy=\"208\" r=\"11\"/><circle data-k=\"7\" class=\"k0\" cx=\"247\" cy=\"220\" r=\"11\"/><circle data-k=\"8\" class=\"k0\" cx=\"220\" cy=\"224\" r=\"11\"/><circle data-k=\"9\" class=\"k0\" cx=\"193\" cy=\"220\" r=\"11\"/><circle data-k=\"10\" class=\"k0\" cx=\"169\" cy=\"208\" r=\"11\"/><circle data-k=\"11\" class=\"k0\" cx=\"150\" cy=\"189\" r=\"11\"/><circle data-k=\"12\" class=\"k0\" cx=\"138\" cy=\"111\" r=\"11\"/><circle data-k=\"13\" class=\"k0\" cx=\"150\" cy=\"87\" r=\"11\"/><circle data-k=\"14\" class=\"k0\" cx=\"169\" cy=\"68\" r=\"11\"/><circle data-k=\"15\" class=\"k0\" cx=\"193\" cy=\"56\" r=\"11\"/></g></svg></div></div><div class=\"af\" data-cap=\"Continuity: the eye follows two smooth paths through the crossing\"><div style=\"overflow-x:auto\"><svg viewBox=\"0 0 440 250\" role=\"img\" aria-label=\"Dots along a line and a curve that cross\" style=\"width:100%;max-width:440px;min-width:280px;display:block;margin:0 auto;font-family:var(--mono)\"><text class=\"tv\" x=\"14\" y=\"24\">Continuity</text><circle data-k=\"0\" class=\"k0\" cx=\"70\" cy=\"138\" r=\"11\"/><circle data-k=\"1\" class=\"k0\" cx=\"110\" cy=\"138\" r=\"11\"/><circle data-k=\"2\" class=\"k0\" cx=\"150\" cy=\"138\" r=\"11\"/><circle data-k=\"3\" class=\"k0\" cx=\"190\" cy=\"138\" r=\"11\"/><circle data-k=\"4\" class=\"k0\" cx=\"230\" cy=\"138\" r=\"11\"/><circle data-k=\"5\" class=\"k0\" cx=\"270\" cy=\"138\" r=\"11\"/><circle data-k=\"6\" class=\"k0\" cx=\"310\" cy=\"138\" r=\"11\"/><circle data-k=\"7\" class=\"k0\" cx=\"350\" cy=\"138\" r=\"11\"/><circle data-k=\"8\" class=\"k0\" cx=\"90\" cy=\"195\" r=\"11\"/><circle data-k=\"9\" class=\"k0\" cx=\"130\" cy=\"162\" r=\"11\"/><circle data-k=\"10\" class=\"k0\" cx=\"170\" cy=\"114\" r=\"11\"/><circle data-k=\"11\" class=\"k0\" cx=\"210\" cy=\"81\" r=\"11\"/><circle data-k=\"12\" class=\"k0\" cx=\"250\" cy=\"81\" r=\"11\"/><circle data-k=\"13\" class=\"k0\" cx=\"290\" cy=\"114\" r=\"11\"/><circle data-k=\"14\" class=\"k0\" cx=\"330\" cy=\"162\" r=\"11\"/><circle data-k=\"15\" class=\"k0\" cx=\"370\" cy=\"195\" r=\"11\"/></svg></div></div><div class=\"af\" data-cap=\"Two paths, a straight line and an arch, not a chain of bent pieces\"><div style=\"overflow-x:auto\"><svg viewBox=\"0 0 440 250\" role=\"img\" aria-label=\"The two paths drawn in\" style=\"width:100%;max-width:440px;min-width:280px;display:block;margin:0 auto;font-family:var(--mono)\"><text class=\"tv\" x=\"14\" y=\"24\">Continuity</text><path class=\"ln\" d=\"M70 138L350 138\"/><path class=\"ln\" d=\"M70 200L85 197L100 190L115 177L130 162L145 144L160 126L175 109L190 94L205 83L220 77L235 76L250 81L265 90L280 104L295 120L310 138L325 156L340 172L355 186L370 195\"/><circle data-k=\"0\" class=\"k0\" cx=\"70\" cy=\"138\" r=\"11\"/><circle data-k=\"1\" class=\"k0\" cx=\"110\" cy=\"138\" r=\"11\"/><circle data-k=\"2\" class=\"k0\" cx=\"150\" cy=\"138\" r=\"11\"/><circle data-k=\"3\" class=\"k0\" cx=\"190\" cy=\"138\" r=\"11\"/><circle data-k=\"4\" class=\"k0\" cx=\"230\" cy=\"138\" r=\"11\"/><circle data-k=\"5\" class=\"k0\" cx=\"270\" cy=\"138\" r=\"11\"/><circle data-k=\"6\" class=\"k0\" cx=\"310\" cy=\"138\" r=\"11\"/><circle data-k=\"7\" class=\"k0\" cx=\"350\" cy=\"138\" r=\"11\"/><circle data-k=\"8\" class=\"k1\" cx=\"90\" cy=\"195\" r=\"11\"/><circle data-k=\"9\" class=\"k1\" cx=\"130\" cy=\"162\" r=\"11\"/><circle data-k=\"10\" class=\"k1\" cx=\"170\" cy=\"114\" r=\"11\"/><circle data-k=\"11\" class=\"k1\" cx=\"210\" cy=\"81\" r=\"11\"/><circle data-k=\"12\" class=\"k1\" cx=\"250\" cy=\"81\" r=\"11\"/><circle data-k=\"13\" class=\"k1\" cx=\"290\" cy=\"114\" r=\"11\"/><circle data-k=\"14\" class=\"k1\" cx=\"330\" cy=\"162\" r=\"11\"/><circle data-k=\"15\" class=\"k1\" cx=\"370\" cy=\"195\" r=\"11\"/></svg></div></div></div><figcaption style=\"margin-top:10px;font-size:13px;line-height:1.45;color:var(--ink-3)\">Nothing about the dots changes except where they sit or how they look, yet the groups you see change every time.</figcaption></figure><!--/viz:pom-anim-gestalt-dots-->"
